<?php $pageTitle='Cleaning Records';require 'includes/header.php';$records=$pdo->query("SELECT cr.*,gt.trap_code,gt.location FROM cleaning_records cr JOIN grease_traps gt ON gt.id=cr.grease_trap_id ORDER BY cr.cleaning_date DESC,cr.id DESC")->fetchAll();?>
<section class="panel"><div class="panel-head"><div><h3>Cleaning History</h3><p>Record of completed grease trap cleanings.</p></div><a class="btn primary" href="add_cleaning.php">+ Record Cleaning</a></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Trap</th><th>Location</th><th>Date</th><th>Cleaned By</th><th>Remarks</th></tr></thead><tbody><?php foreach($records as $r):?><tr><td>#<?=$r['id']?></td><td><strong><?=h($r['trap_code'])?></strong></td><td><?=h($r['location'])?></td><td><?=date('d M Y',strtotime($r['cleaning_date']))?></td><td><?=h($r['cleaned_by'])?></td><td><?=h($r['remarks']?:'—')?></td></tr><?php endforeach;?></tbody></table></div></section><?php require 'includes/footer.php';?>